(()=>{function e(){const n=document.querySelector(".nav-tabs");document.getElementById("tools-page").querySelectorAll("[data-i18n]").forEach(t=>{const s=t.getAttribute("data-i18n"),o=chrome.i18n.getMessage(s);t&&o&&(t.id.includes("tool-item-")?t.setAttribute("data-tooltip",o):t.textContent=o)}),document.querySelectorAll(".tool-item").forEach(t=>{t.classList.contains("comming-soon")||t.addEventListener("click",()=>{window.PopupAPI.loadPage(t.dataset.target),n.classList.add("d-none")})})}e()})();
